-- 1) COMANDO PARA SELECIONAR O NUMERO DA OS E A SOMA DAS METRAGENS RETIRADAS, AGRUPANDO PELO NUMERO DA OS. o 'AS' NO FINAL DO COMANDO É PARA DAR UM NOME PARA A COLUNA QUE VAI RETORNAR A SOMA DAS METRAGENS RETIRADAS.
SELECT NUMERO_OS, SUM(METRAGEM_RETIRADA) AS TOTAL_METROS FROM TB_MOVIMENTACAO GROUP BY NUMERO_OS

-- 2) COMANDO PARA SELECIONAR O TIPO DE MATERIAL E A SOMA DAS METRAGENS RETIRADAS, AGRUPANDO PELO TIPO DE MATERIAL. o 'AS' NO FINAL DO COMANDO É PARA DAR UM NOME PARA A COLUNA QUE VAI RETORNAR A SOMA DAS METRAGENS RETIRADAS.
SELECT B.TIPO_MATERIAL, SUM(M.METRAGEM_RETIRADA) AS TOTAL_METROS FROM TB_MOVIMENTACAO M JOIN TB_BOBINA B ON B.ID = M.BOBINA_ID GROUP BY B.TIPO_MATERIAL

-- 3) COMANDO PARA SELECIONAR O TIPO DE MATERIAL E A QUANTIDADE DE RETIRADAS, AGRUPANDO PELO TIPO DE MATERIAL. o 'AS' NO FINAL DO COMANDO É PARA DAR UM NOME PARA A COLUNA QUE VAI RETORNAR A QUANTIDADE DE RETIRADAS.
SELECT B.TIPO_MATERIAL, COUNT(M.METRAGEM_RETIRADA) AS QUANTIDADE_RETIRADA FROM TB_MOVIMENTACAO M JOIN TB_BOBINA B ON B.ID = M.BOBINA_ID GROUP BY B.TIPO_MATERIAL

-- 4) COMANDO PARA SELECIONAR O TIPO DE MATERIAL E A MÉDIA DAS METRAGENS RETIRADAS, AGRUPANDO PELO TIPO DE MATERIAL. o 'AS' NO FINAL DO COMANDO É PARA DAR UM NOME PARA A COLUNA QUE VAI RETORNAR A MÉDIA DAS METRAGENS RETIRADAS.
SELECT B.TIPO_MATERIAL, AVG(M.METRAGEM_RETIRADA) AS MEDIA_RETIRADA FROM TB_MOVIMENTACAO M JOIN TB_BOBINA B ON B.ID = M.BOBINA_ID GROUP BY B.TIPO_MATERIAL

-- 5) COMANDO PARA SELECIONAR O ID, TIPO DE MATERIAL E METRAGEM LINEAR DAS BOBINAS QUE POSSUEM METRAGEM LINEAR MENOR QUE 1000. o 'AS' NO FINAL DO COMANDO É PARA DAR UM NOME PARA A COLUNA QUE VAI RETORNAR A METRAGEM LINEAR.
SELECT ID, TIPO_MATERIAL, METRAGEM_LINEAR AS METRAGEM FROM TB_BOBINA WHERE METRAGEM_LINEAR < 1000